from rdkit import Chem
from rdkit.Chem import AllChem
import json
rw=Chem.RWMol(); names={}
def atom(sym,name=None,charge=0):
 a=Chem.Atom(sym); a.SetFormalCharge(charge)
 if sym=='Sn': a.SetNoImplicit(True)
 idx=rw.AddAtom(a)
 if name:names[name]=idx
 return idx
def bond(a,b,t=Chem.BondType.SINGLE): rw.AddBond(a,b,t)
def carbon(name=None):return atom('C',name)
def phenyl(base,name,perfluoro=False,dipp=False):
 ids=[atom('C',name+str(k)) for k in range(6)]
 for i in range(6):bond(ids[i],ids[(i+1)%6],Chem.BondType.AROMATIC)
 for i in ids:rw.GetAtomWithIdx(i).SetIsAromatic(True)
 bond(base,ids[0])
 if perfluoro:
  for i in ids[1:]:bond(i,atom('F'))
 if dipp:
  for i in [1,5]:
   j=carbon();bond(ids[i],j);bond(j,carbon());bond(j,carbon())
 return ids
# central phosphalkene and chelate skeleton
p=atom('P','P'); pc=carbon('PC'); o=atom('O','O'); sn=atom('Sn','Sn',1)
u=atom('N','NU'); v=atom('N','NL'); iu=carbon('CU'); il=carbon('CL'); bridge=carbon('bridge')
bond(p,pc,Chem.BondType.DOUBLE);bond(pc,o);bond(o,sn)
bond(u,sn,Chem.BondType.DATIVE);bond(v,sn,Chem.BondType.DATIVE)
bond(u,iu,Chem.BondType.DOUBLE);bond(v,il,Chem.BondType.DOUBLE)
bond(iu,bridge);bond(il,bridge);bond(bridge,p)
mu=carbon('MU');ml=carbon('ML');bond(iu,mu);bond(il,ml)
phenyl(u,'DippU',dipp=True);phenyl(v,'DippL',dipp=True)
# external alkene and tri(pentafluorophenyl)borate
ac=carbon('AC'); bc=carbon('BC'); bor=atom('B','B',-1)
bond(pc,ac);bond(ac,bc,Chem.BondType.DOUBLE);bond(bc,bor)
phenyl(ac,'Ph')
for k in range(3):phenyl(bor,'BAr'+str(k)+'_',perfluoro=True)
m=rw.GetMol();Chem.SanitizeMol(m)
ab=m.GetBondBetweenAtoms(ac,bc);ab.SetStereoAtoms(pc,bor);ab.SetStereo(Chem.BondStereo.STEREOE)
Chem.AssignStereochemistry(m,cleanIt=False,force=True)
print(Chem.MolToSmiles(m));print(names)
m=Chem.AddHs(m)
print('atoms:',m.GetNumAtoms());print('UFF has all params',AllChem.UFFHasAllMoleculeParams(m))
params=AllChem.ETKDGv3();params.randomSeed=30;params.numThreads=4;params.useRandomCoords=True;params.maxIterations=3000
